When reading and parsing JSON input files, we should wrap the path resolution and file reading logic to catch errors and record diagnostics rather than throwing unhandled exceptions or silently returning null. This ensures the system fails closed gracefully with clear error messages.

```javascript
function readJsonInput(root, relPath, role, diagnostics) {
  const target = resolvePath(root, relPath);
  try {
    if (!target) throw new TypeError('root and relPath must be strings');
    if (!fs.existsSync(target)) {
      if (diagnostics) {
        diagnostics.push({
          code: 'input_artifact_missing',
          role,
          path: relPath,
          severity: 'critical',
        });
      }
      return null;
    }
    return JSON.parse(fs.readFileSync(target, 'utf8'));
  } catch (error) {
    if (diagnostics) {
      diagnostics.push({
        code: 'input_artifact_malformed',
        role,
        path: relPath,
        severity: 'critical',
        reason: error instanceof Error ? error.message : String(error),
      });
    }
    return null;
  }
}
